#ifndef SIRKIT_UPPER_SQUARE_DEFINED
#define SIRKIT_UPPER_SQUARE_DEFINED
template <class T> std::vector<T> NAME_square(std::vector<T> f, const IntegerSieve& sieve) {
#ifndef SKIP_RUNTIME_CHECKS
    reinsirk::detail::IntegerTransform::require_sieve(f.size(), sieve);
#endif
    return reinsirk::detail::IntegerConvolution::square<GCD>(std::move(f), sieve.prime_list);
