from pathlib import Path
import subprocess,json,statistics,fcntl,hashlib
p=Path(__file__).parent;variants=['baseline','control','final'];ccs={'gcc':['g++'],'clang':['clang++','--gcc-install-dir=/opt/atcoder/gcc/lib/gcc/x86_64-pc-linux-gnu/15.3.0']};builds=[]
for cc,args in ccs.items():
 for v in variants:
  cmd=['taskset','-c','6',*args,'-std=c++23','-O2','-DSKIP_RUNTIME_CHECKS','-DSOURCE="'+str(p/(v+'.hpp'))+'"',str(p/'api_bench.cpp'),'-o',str(p/(cc+'_'+v))]+(['-DSIRKIT_ZETA_INTEGER_EXTRA']if v=='final'else[]);subprocess.run(cmd,capture_output=True,check=True);builds.append(dict(command=cmd,header_sha256=hashlib.sha256((p/(v+'.hpp')).read_bytes()).hexdigest()))
raw={};checks={};loops={}
with open(str(p.parent/'benchmark_zeta.lock'),'a')as lock:
 fcntl.flock(lock,fcntl.LOCK_EX)
 for cc in ccs:
  for typ in ['mod','u64']:
   for n in [0,1,2,32,129,4096,262144,1000001]:
    for mode in range(7):
     if typ=="u64"and mode==6:continue
     key=f'{cc}_{typ}_{n}_{mode}';pilot=subprocess.check_output(['taskset','-c','14',str(p/(cc+'_baseline')),str(n),str(mode),'1',typ],text=True).split();count=max(1,min(200000,int(20/max(float(pilot[0]),0.0001))));loops[key]=count;raw[key]={v:[]for v in variants};checks[key]={}
     for rep in range(7):
      vs=variants[rep%3:]+variants[:rep%3]
      for v in vs:
       out=subprocess.check_output(['taskset','-c','14',str(p/(cc+'_'+v)),str(n),str(mode),str(count),typ],text=True).split();raw[key][v].append(float(out[0]));checks[key][v]=out[1]
     assert len(set(checks[key].values()))==1,key
     print(key,{v:round(statistics.median(xs)/statistics.median(raw[key]['baseline']),3)for v,xs in raw[key].items()},flush=True)
med={k:{v:statistics.median(xs)for v,xs in vs.items()}for k,vs in raw.items()};ratios={k:{v:x/vs['baseline']for v,x in vs.items()}for k,vs in med.items()};(p/'final_api.json').write_text(json.dumps(dict(status='PASS',raw_ms=raw,medians_ms=med,ratios=ratios,checksums=checks,loops=loops,builds=builds),indent=2)+'\n')

